import * as PIXI from 'pixi.js';

/**
 * ROM bitmap font renderer (sprites/font_main.* and font_alt.*, generated by
 * robotron-re/tools/extract_font2.py).
 *
 * main: 47 glyphs '0'-'^' (5 px tall) — in-game text, score digits.
 * alt:  30 glyphs '0'-'M' (larger)   — title / attract headlines.
 *
 * Glyphs are white in the sheet; use `tint` for the arcade's red/yellow/
 * green text colors.
 */

interface GlyphMeta { x: number; y: number; w: number; h: number; }
interface FontMeta { lineHeight: number; glyphs: Record<string, GlyphMeta>; }

interface LoadedFont {
    source: PIXI.TextureSource;
    meta: FontMeta;
    cache: Map<string, PIXI.Texture>;
}

const fonts = new Map<string, LoadedFont>();
const DASH_W = 3;
// ')' is outside the extracted '0'-'^' range; the heroes table's rank separator,
// copied from a MAME snapshot (6 rows in the alt font; the main font drops one)
const PAREN: Record<string, string[]> = {
    font_alt: ['#..', '.#.', '..#', '..#', '.#.', '#..'],
    font_main: ['#..', '.#.', '..#', '.#.', '#..'],
};
const PAREN_W = 3;

async function loadFont(name: 'font_main' | 'font_alt'): Promise<void> {
    if (fonts.has(name)) return;
    // metadata first (no-store), sheet keyed by its version — keeps the
    // PNG/JSON pair consistent across browser caches (see ArcadeAtlas)
    const meta = await (await fetch(`sprites/${name}.json`, { cache: 'no-store' })).json();
    const sheet = await PIXI.Assets.load(`sprites/${name}.png?v=${(meta as any).version ?? 0}`);
    sheet.source.scaleMode = 'nearest';
    fonts.set(name, { source: sheet.source, meta, cache: new Map() });
}

function glyphTexture(font: LoadedFont, ch: string): PIXI.Texture | null {
    const cached = font.cache.get(ch);
    if (cached) return cached;
    const g = font.meta.glyphs[ch];
    if (!g) return null;
    const tex = new PIXI.Texture({
        source: font.source,
        frame: new PIXI.Rectangle(g.x, g.y, g.w, g.h),
    });
    font.cache.set(ch, tex);
    return tex;
}

export interface BitmapTextOptions {
    font?: 'main' | 'alt';
    tint?: number;
    /** extra pixels between characters (arcade default 1) */
    tracking?: number;
}

export const BitmapFont = {
    async load(): Promise<void> {
        await Promise.all([loadFont('font_main'), loadFont('font_alt')]);
    },

    isLoaded(): boolean { return fonts.size === 2; },

    lineHeight(fontName: 'main' | 'alt' = 'main'): number {
        return fonts.get(`font_${fontName}`)?.meta.lineHeight ?? 5;
    },

    /**
     * Build a Container of glyph sprites for `text`. Unknown characters
     * (including space) advance the cursor by a glyph width.
     * The ROM remaps ' ' to a blank column, uppercases letters.
     */
    createText(text: string, opts: BitmapTextOptions = {}): PIXI.Container {
        const fontName = `font_${opts.font ?? 'main'}`;
        const font = fonts.get(fontName);
        const container = new PIXI.Container();
        if (!font) return container;
        const tracking = opts.tracking ?? 1;
        const spaceW = (font.meta.glyphs['0']?.w ?? 4);
        let x = 0;
        for (const raw of text.toUpperCase()) {
            const tex = glyphTexture(font, raw);
            if (!tex && raw === '-') {
                // the ROM charset ('0'-'^') has no hyphen: synthesize one
                const dash = new PIXI.Graphics()
                    .rect(0, Math.floor(font.meta.lineHeight / 2), DASH_W, 1)
                    .fill(opts.tint ?? 0xFFFFFF);
                dash.x = x;
                container.addChild(dash);
                x += DASH_W + tracking;
                continue;
            }
            if (!tex && raw === ')') {
                const g = new PIXI.Graphics();
                (PAREN[fontName] ?? PAREN.font_main).forEach((row, yy) => {
                    for (let xx = 0; xx < row.length; xx++) if (row[xx] === '#') g.rect(xx, yy, 1, 1);
                });
                g.fill(opts.tint ?? 0xFFFFFF);
                g.x = x;
                container.addChild(g);
                x += PAREN_W + tracking;
                continue;
            }
            if (!tex) { x += spaceW + tracking; continue; }
            const spr = new PIXI.Sprite(tex);
            spr.x = x;
            if (opts.tint !== undefined) spr.tint = opts.tint;
            container.addChild(spr);
            x += tex.width + tracking;
        }
        return container;
    },

    /** Update an existing text container in place (cheap re-render). */
    setText(container: PIXI.Container, text: string, opts: BitmapTextOptions = {}): void {
        container.removeChildren().forEach(c => c.destroy());
        const rebuilt = this.createText(text, opts);
        rebuilt.children.slice().forEach(c => container.addChild(c));
    },

    /** Pixel width of `text` without building sprites. */
    measure(text: string, opts: BitmapTextOptions = {}): number {
        const font = fonts.get(`font_${opts.font ?? 'main'}`);
        if (!font) return 0;
        const tracking = opts.tracking ?? 1;
        const spaceW = (font.meta.glyphs['0']?.w ?? 4);
        let x = 0;
        for (const raw of text.toUpperCase()) {
            const g = font.meta.glyphs[raw];
            x += (g ? g.w : raw === '-' ? DASH_W : raw === ')' ? PAREN_W : spaceW) + tracking;
        }
        return Math.max(0, x - tracking);
    },
};
